// Des: Tests for DMs, friend requests, group join
// Flo: new contact needs approval > known contact sends > same message twice skipped > join group > missing args refused
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-dmsg-main-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const task = @import("ru-task-runn.zig"); const dm = @import("ru-dmsg-main.zig");
test "new contact needs --force; after that the contact is known" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); try std.testing.expectError(error.NeedApprove, dm.dmRun(&cx, .{ .to = "42", .text = "Hello Ann" })); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); cx = rig.ctx(.force); try std.testing.expectEqual(task.Out.done, try dm.dmRun(&cx, .{ .to = "42", .text = "Hello Ann" })); try std.testing.expectEqualStrings("Hello Ann", rig.waitRec("dm", 3000).?); try std.testing.expect(try rig.store.knowHas("42")); cx = rig.ctx(.live); try std.testing.expectEqual(task.Out.done, try dm.dmRun(&cx, .{ .to = "42", .text = "Second message" })); }
test "same message to the same person is sent once" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try rig.store.knowAdd("42", 1); var cx = rig.ctx(.live); try std.testing.expectEqual(task.Out.done, try dm.dmRun(&cx, .{ .to = "42", .text = "once" })); _ = rig.waitRec("dm", 3000).?; try std.testing.expectEqual(task.Out.dupe, try dm.dmRun(&cx, .{ .to = "42", .text = "once" })); try std.testing.expectEqual(@as(usize, 1), rig.mock.recNum("dm")); }
test "DM cap is enforced" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.capz_dmsg_dayz = 1; try rig.store.knowAdd("42", 1); var cx = rig.ctx(.live); _ = try dm.dmRun(&cx, .{ .to = "42", .text = "one" }); try std.testing.expectError(error.CapHit, dm.dmRun(&cx, .{ .to = "42", .text = "two" })); }
test "join group clicks once on the group cap" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); try std.testing.expectEqual(task.Out.done, try dm.joinRun(&cx, .{ .url = "/groups/77/" })); try std.testing.expectEqualStrings("77", rig.waitRec("join", 3000).?); try std.testing.expectEqual(task.Out.dupe, try dm.joinRun(&cx, .{ .url = "/groups/77/" })); try std.testing.expectEqual(@as(i64, 1), try rig.store.actCnt("grou", 0)); }
test "missing arguments are refused" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); try std.testing.expectError(error.BadUsage, dm.dmRun(&cx, .{ .to = "42" })); try std.testing.expectError(error.BadUsage, dm.dmRun(&cx, .{ .text = "x" })); try std.testing.expectError(error.BadUsage, dm.joinRun(&cx, .{})); try std.testing.expectError(error.BadUsage, dm.friendRun(&cx, .{})); }
